# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DENEYSEL VERİ TABLOSUNDAN HIZ DENKLEMİ BULMA</text>\n  <rect x="20" y="45" width="340" height="185" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="190" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">ÖRNEK DENEY TABLOSU (2NO + Cl₂ -&gt; 2NOCl)</text>\n  <rect x="35" y="78" width="310" height="96" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="190" y="96" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">Deney | [NO] (M) | [Cl₂] (M) | Başlangıç Hızı (M/s)</text>\n  <line x1="40" y1="102" x2="340" y2="102" stroke="#93c5fd" stroke-width="1"/>\n  <text x="190" y="118" text-anchor="middle" font-size="10" fill="#334155">1. Deney |   0,10   |   0,10    |     2,0 x 10⁻³</text>\n  <text x="190" y="138" text-anchor="middle" font-size="10" fill="#334155">2. Deney |   0,10   |   0,20    |     4,0 x 10⁻³</text>\n  <text x="190" y="158" text-anchor="middle" font-size="10" fill="#334155">3. Deney |   0,20   |   0,10    |     8,0 x 10⁻³</text>\n  <text x="190" y="194" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">1 ve 2: [NO] sabit, [Cl₂] 2 katına -&gt; Hız 2 kat (1. derece)</text>\n  <text x="190" y="212" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">1 ve 3: [Cl₂] sabit, [NO] 2 katına -&gt; Hız 4 kat (2. derece)</text>\n\n  <rect x="375" y="45" width="305" height="185" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="527" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">DERİŞİM ARTIRIMI VE ÜS (DERECE) İLİŞKİSİ</text>\n  <rect x="390" y="78" width="275" height="135" rx="6" fill="#ffffff" stroke="#4ade80" stroke-width="1.2"/>\n  <text x="527" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">[X] Derişimi k Katına Çıktığında:</text>\n  <text x="527" y="118" text-anchor="middle" font-size="9.5" fill="#334155">• Hız değişmiyorsa (k⁰ = 1) -&gt; 0. Derece (Yazılmaz)</text>\n  <text x="527" y="138" text-anchor="middle" font-size="9.5" fill="#334155">• Hız k katına çıkıyorsa (k¹) -&gt; 1. Derece: [X]¹</text>\n  <text x="527" y="158" text-anchor="middle" font-size="9.5" fill="#334155">• Hız k² katına çıkıyorsa -&gt; 2. Derece: [X]²</text>\n  <text x="527" y="178" text-anchor="middle" font-size="9.5" fill="#334155">• Hız k³ katına çıkıyorsa -&gt; 3. Derece: [X]³</text>\n  <text x="527" y="200" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Sonuç: r = k · [NO]² · [Cl₂]¹ (Derece = 3)</text>\n</svg>', '<svg viewBox="0 0 700 220" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="220" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TEPKİME DERECESİNE GÖRE HIZ SABİTİ (k) BİRİMLERİ</text>\n  <rect x="20" y="48" width="210" height="152" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="125" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">1. DERECE (n = 1)</text>\n  <text x="125" y="94" text-anchor="middle" font-size="10" fill="#334155">Örnek: r = k · [X]¹</text>\n  <text x="125" y="118" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">k birimi: 1/s = s⁻¹</text>\n  <text x="125" y="144" text-anchor="middle" font-size="9.5" fill="#334155">(L/mol)¹⁻¹ · (1/s) = 1/s</text>\n  <text x="125" y="166" text-anchor="middle" font-size="9.5" fill="#334155">Hız derişimle doğru orantılıdır.</text>\n\n  <rect x="245" y="48" width="210" height="152" rx="10" fill="#e0e7ff" stroke="#4f46e5" stroke-width="1.8"/>\n  <text x="350" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#3730a3">2. DERECE (n = 2)</text>\n  <text x="350" y="94" text-anchor="middle" font-size="10" fill="#334155">Örnek: r = k · [X] · [Y] veya k · [X]²</text>\n  <text x="350" y="118" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#4338ca">k birimi: L / (mol · s) = M⁻¹·s⁻¹</text>\n  <text x="350" y="144" text-anchor="middle" font-size="9.5" fill="#334155">(L/mol)²⁻¹ · (1/s) = L/(mol·s)</text>\n  <text x="350" y="166" text-anchor="middle" font-size="9.5" fill="#334155">Hacim yarıya inerse hız 4 katına çıkar.</text>\n\n  <rect x="470" y="48" width="210" height="152" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="575" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">3. DERECE (n = 3)</text>\n  <text x="575" y="94" text-anchor="middle" font-size="10" fill="#334155">Örnek: r = k · [X]² · [Y]¹</text>\n  <text x="575" y="118" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7e22ce">k birimi: L² / (mol² · s) = M⁻²·s⁻¹</text>\n  <text x="575" y="144" text-anchor="middle" font-size="9.5" fill="#334155">(L/mol)³⁻¹ · (1/s) = L²/(mol²·s)</text>\n  <text x="575" y="166" text-anchor="middle" font-size="9.5" fill="#334155">Hacim yarıya inerse hız 8 katına çıkar.</text>\n</svg>', '<svg viewBox="0 0 700 210" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="210" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HIZ DENKLEMİ İLE TAHMİN VE KAP HACMİ ETKİSİ</text>\n  <rect x="20" y="48" width="320" height="142" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.8"/>\n  <text x="180" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0369a1">DERİŞİM DEĞİŞİMİ TAHMİNİ</text>\n  <text x="180" y="94" text-anchor="middle" font-size="10" font-weight="bold" fill="#0284c7">Bağıntı: r = k · [X]² · [Y]¹</text>\n  <text x="180" y="116" text-anchor="middle" font-size="9.5" fill="#334155">• [X] 2 katına, [Y] 3 katına çıkarsa:</text>\n  <text x="180" y="134" text-anchor="middle" font-size="10" font-weight="bold" fill="#334155">r_yeni = (2)² · (3)¹ · r = 12 · r (12 katına çıkar)</text>\n  <text x="180" y="156" text-anchor="middle" font-size="9.5" fill="#334155">• Sabit sıcaklıkta k hız sabiti değişmez!</text>\n\n  <rect x="360" y="48" width="320" height="142" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="520" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">GAZLARDA KAP HACMİ (M = n / V)</text>\n  <text x="520" y="94" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">Bağıntı: r = k · [X]² · [Y]¹ (Derece n = 3)</text>\n  <text x="520" y="116" text-anchor="middle" font-size="9.5" fill="#334155">• Kap hacmi yarıya (V/2) indirilirse:</text>\n  <text x="520" y="134" text-anchor="middle" font-size="9.5" fill="#334155">[X] -&gt; 2[X] ve [Y] -&gt; 2[Y] olur.</text>\n  <text x="520" y="154" text-anchor="middle" font-size="10" font-weight="bold" fill="#991b1b">r_yeni = (2)² · (2)¹ · r = 8 · r (8 katına çıkar)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
